{"cards": [{"node_code": "N_877492f418d72e45", "definition": "研究铁路车辆制造中使用的金属材料、非金属材料及其性能、选用标准与处理工艺，涵盖车体、转向架等关键部件的材料科学内容。", "boundary": "本节点聚焦于“材料”本身及其在车辆制造中的应用。边界在于区分“材料”与“设计”（材料选型归本节点，结构强度计算归车辆设计）、“材料”与“工艺”（材料性能归本节点，焊接/成型工艺归车辆制造工艺）。若涉及材料在特定工况下的失效分析，需结合车辆理论及试验。", "includes": ["车体用钢、铝合金、复合材料等基础材料性能研究", "车辆关键部件（如转向架、车钩）的材料选用标准与热处理工艺"], "excludes": ["车辆整体结构设计、强度计算与仿真分析", "具体的焊接、冲压、组装等制造工艺过程", "车辆运行中的材料疲劳寿命预测（归入车辆理论及试验）"], "sibling_distinctions": [{"other_code": "N_3afde9fabafff065", "rule": "区分依据为对象：本节点关注材料属性与选型，兄弟节点关注基于材料属性的结构设计与力学计算。"}, {"other_code": "N_db8d4317aa7e67cd", "rule": "区分依据为过程：本节点关注材料本身的特性与准备，兄弟节点关注将材料转化为零部件的加工与装配工艺。"}], "cross_boundary_rule": "若内容涉及“材料-工艺-性能”一体化研究，若侧重材料微观组织与宏观性能关系，主挂载本节点；若侧重工艺参数对性能的影响，可关联车辆制造工艺。"}, {"node_code": "N_db8d4317aa7e67cd", "definition": "研究铁路车辆零部件及总成的加工、装配、焊接、涂装等制造工艺方法、生产线布局及质量控制技术，涵盖从原材料到成品的制造全过程。", "boundary": "本节点聚焦于“制造过程”与“工艺方法”。边界在于区分“工艺”与“设计”（工艺可行性归本节点，功能设计归车辆设计）、“工艺”与“材料”（加工工艺归本节点，材料基础性能归车辆制造用材料）。若涉及制造过程中的自动化控制或智能工厂管理，需视具体技术细节归属。", "includes": ["车体焊接、冲压、铆接等连接工艺及涂装防腐技术", "转向架、制动系统等关键部件的装配工艺与生产线组织"], "excludes": ["车辆结构原理设计与强度校核计算", "基础材料的成分、微观组织及基础物理化学性能研究", "车辆出厂后的运用、保养与检修规程"], "sibling_distinctions": [{"other_code": "N_877492f418d72e45", "rule": "区分依据为阶段：本节点关注材料如何被加工成零件（工艺），兄弟节点关注材料本身的属性与选型（材料）。"}, {"other_code": "N_3afde9fabafff065", "rule": "区分依据为职能：本节点关注“怎么做”（制造实现），兄弟节点关注“做什么”（功能与结构设计）。"}], "cross_boundary_rule": "若内容涉及“工艺设计”，若侧重工艺路线规划与工装设计，主挂载本节点；若侧重工艺对结构强度的影响分析，可关联车辆设计、计算。"}, {"node_code": "N_df7a3559aa107298", "definition": "研究铁路车辆性能检测、故障诊断、状态监测的测试方法、实验技术及专用仪器设备，涵盖静态与动态测试、环境模拟试验等内容。", "boundary": "本节点聚焦于“测试手段”与“仪器工具”。边界在于区分“测试”与“理论”（测试数据获取归本节点，数据建模与理论分析归车辆理论及试验）、“测试”与“检修”（测试技术归本节点，基于测试结果的维修决策归车辆运用、保养与检修）。若涉及测试数据的算法处理，需视是否属于基础理论范畴。", "includes": ["车辆动力学、疲劳、噪声振动等性能测试方法与实验台架", "车辆状态监测传感器、数据采集系统及专用测试仪器"], "excludes": ["基于测试数据的车辆动力学理论建模与仿真分析", "车辆日常运用中的例行检查与故障维修作业", "车辆结构设计、制造工艺及材料基础性能研究"], "sibling_distinctions": [{"other_code": "N_43f369073fdbf6c1", "rule": "区分依据为侧重点：本节点关注“如何测”（方法、仪器、实验过程），兄弟节点关注“测什么”及“数据解释”（理论模型、机理分析）。"}, {"other_code": "N_25dca136c0293f43", "rule": "区分依据为阶段：本节点关注制造或研发阶段的性能验证测试，兄弟节点关注运用阶段的故障诊断与检修技术。"}], "cross_boundary_rule": "若内容涉及“测试与诊断”，若侧重测试系统硬件与实验方法，主挂载本节点；若侧重基于测试数据的故障机理分析与理论模型，可关联车辆理论及试验。"}]}
